        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        bool secondReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }
